program.source:
Algorithm Primo
  Define n As Integer;
  Read n;
  Define esPrimo As Boolean <- True;
  For d <- 2 To n - 1 Do
    If n Mod d = 0 Then
      esPrimo <- False;
      Break;
    EndIf
  EndFor
  If esPrimo Then
    Write "Es primo";
  Else
    Write "No es primo";
  EndIf
EndAlgorithm

